    80          // eslint-disable-next-line rulesdir/no-api-side-effects-method
    81          API.makeRequestWithSideEffects(SIDE_EFFECT_REQUEST_COMMANDS.OPEN_OLD_DOT_LINK, {}, {})
    82              .then((response) => (response ? buildOldDotURL(url, response.shortLivedAuthToken) : buildOldDotURL(url)))
    83              .catch(() => buildOldDotURL(url)),
    84          (oldDotURL) => oldDotURL,
    85      );
    86  }
