    92      const authCode = `authCode=${spotnanaToken}`;
    93      const tmcIDParam = `tmcId=${tmcID}`;
    94      const redirectURL = postLoginPath ? `redirectUrl=${Url.addLeadingForwardSlash(postLoginPath)}` : '';
