   119              API.makeRequestWithSideEffects(SIDE_EFFECT_REQUEST_COMMANDS.GENERATE_SPOTNANA_TOKEN, parameters, {})
   120                  .then((response) => {
   121                      if (!response?.spotnanaToken) {
