   123                          throw error;
   124                      }
   125                      return buildTravelDotURL(response.spotnanaToken, postLoginPath);
   126                  })
   127                  .catch(() => {
   128                      reject(error);
   129                      throw error;
   130                  }),
   131              (travelDotURL) => travelDotURL ?? '',
   132          );
   133      });
   134  }
