   144  function getInternalExpensifyPath(href: string) {
   145      const attrPath = Url.getPathFromURL(href);
   146      const hasExpensifyOrigin = Url.hasSameExpensifyOrigin(href, CONFIG.EXPENSIFY.EXPENSIFY_URL) || Url.hasSameExpensifyOrigin(href, CONFIG.EXPENSIFY.STAGING_API_ROOT);
   147      if (!hasExpensifyOrigin || attrPath.startsWith(CONFIG.EXPENSIFY.CONCIERGE_URL_PATHNAME) || attrPath.startsWith(CONFIG.EXPENSIFY.DEVPORTAL_URL_PATHNAME)) {
   148          return '';
   149      }
   150
   151      return attrPath;
   152  }
   153
   154  function openLink(href: string, environmentURL: string, isAttachment = false) {
   155      const hasSameOrigin = Url.hasSameExpensifyOrigin(href, environmentURL);
   156      const hasExpensifyOrigin = Url.hasSameExpensifyOrigin(href, CONFIG.EXPENSIFY.EXPENSIFY_URL) || Url.hasSameExpensifyOrigin(href, CONFIG.EXPENSIFY.STAGING_API_ROOT);
   157      const internalNewExpensifyPath = getInternalNewExpensifyPath(href);
   158      const internalExpensifyPath = getInternalExpensifyPath(href);
   159
   160      // There can be messages from Concierge with links to specific NewDot reports. Those URLs look like this:
   161      // https://www.expensify.com.dev/newdotreport?reportID=3429600449838908 and they have a target="_blank" attribute. This is so that when a user is on OldDot,
   162      // clicking on the link will open the chat in NewDot. However, when a user is in NewDot and clicks on the concierge link, the link needs to be handled differently.
   163      // Normally, the link would be sent to Link.openOldDotLink() and opened in a new tab, and that's jarring to the user. Since the intention is to link to a specific NewDot chat,
   164      // the reportID is extracted from the URL and then opened as an internal link, taking the user straight to the chat in the same tab.
   165      if (hasExpensifyOrigin && href.indexOf('newdotreport?reportID=') > -1) {
   166          const reportID = href.split('newdotreport?reportID=').pop();
   167          const reportRoute = ROUTES.REPORT_WITH_ID.getRoute(reportID ?? '-1');
   168          Navigation.navigate(reportRoute);
   169          return;
   170      }
   171
   172      // If we are handling a New Expensify link then we will assume this should be opened by the app internally. This ensures that the links are opened internally via react-navigation
   173      // instead of in a new tab or with a page refresh (which is the default behavior of an anchor tag)
   174      if (internalNewExpensifyPath && hasSameOrigin) {
   175          if (Session.isAnonymousUser() && !Session.canAnonymousUserAccessRoute(internalNewExpensifyPath)) {
   176              Session.signOutAndRedirectToSignIn();
   177              return;
   178          }
   179          Navigation.navigate(internalNewExpensifyPath as Route);
   180          return;
   181      }
   182
   183      // If we are handling an old dot Expensify link we need to open it with openOldDotLink() so we can navigate to it with the user already logged in.
   184      // As attachments also use expensify.com we don't want it working the same as links.
   185      if (internalExpensifyPath && !isAttachment) {
   186          openOldDotLink(internalExpensifyPath);
   187          return;
   188      }
   189
   190      openExternalLink(href);
   191  }
