    20  import {Linking} from 'react-native';
    21  import Log from '@libs/Log';
    22  import type AsyncOpenURL from './types';
    23
    24  /**
    25   * Prevents Safari from blocking pop-up window when opened within async call.
    26   * @param shouldSkipCustomSafariLogic When true, we will use `Linking.openURL` even if the browser is Safari.
    27   */
    28  const asyncOpenURL: AsyncOpenURL = (promise, url, shouldSkipCustomSafariLogic) => {
    29      if (!url) {
    30          return;
    31      }
    32
    33      const isSafari = /^((?!chrome|android).)*safari/i.test(navigator.userAgent);
    34
    35      if (!isSafari || shouldSkipCustomSafariLogic) {
    36          promise
    37              .then((params) => {
    38                  Linking.openURL(typeof url === 'string' ? url : url(params));
    39              })
    40              .catch(() => {
    41                  Log.warn('[asyncOpenURL] error occured while opening URL', {url});
    42              });
    43      } else {
    44          const windowRef = window.open();
    45          promise
    46              .then((params) => {
    47                  if (!windowRef) {
    48                      return;
    49                  }
    50                  windowRef.location = typeof url === 'string' ? url : url(params);
    51              })
    52              .catch(() => {
    53                  windowRef?.close();
    54                  Log.warn('[asyncOpenURL] error occured while opening URL', {url});
    55              });
    56      }
    57  };
    58
    59  export default asyncOpenURL;
    60  type AsyncOpenURL = <T>(promise: Promise<T>, url: string | ((params: T) => string), shouldSkipCustomSafariLogic?: boolean) => void;
    61
    62  export default AsyncOpenURL;

